[{"location":"#Librdkafka.jl","page":"Home","title":"Librdkafka.jl","text":"Julia wrapper for librdkafka.","category":"section"},{"location":"#Installation","page":"Home","title":"Installation","text":"If you haven't installed our local registry yet, do that first:\n\n] registry add https://github.com/bhftbootcamp/Green.git\n\nTo install Librdkafka, simply use the Julia package manager:\n\n] add Librdkafka","category":"section"},{"location":"#Usage","page":"Home","title":"Usage","text":"","category":"section"},{"location":"#Producer","page":"Home","title":"Producer","text":"using Librdkafka\n\ntopic = \"julia-demo\"\n\np = KafkaProducer(\"localhost:9092\")\n\ntry\n    i = 1\n    while true\n        msg = \"hello #$i from julia\"\n        produce(p, topic, 0, \"key\", msg)\n        @info \"Sent\" msg\n        i += 1\n        sleep(1)\n    end\nfinally\n    close(p) # unreachable here, Ctrl+C to stop\nend","category":"section"},{"location":"#Consumer","page":"Home","title":"Consumer","text":"using Librdkafka\n\ntopic = \"julia-demo\"\n\nc = KafkaConsumer(\n    \"localhost:9092\";\n    group_id = \"julia-demo-consumer\",\n    config = Dict(\n        AUTO_OFFSET_RESET => \"earliest\",\n        ENABLE_AUTO_COMMIT => \"false\",\n    ),\n)\n\nsubscribe!(c, [topic])\n\ntry\n    while true\n        for r in poll(c; timeout_ms=1000)\n            @info \"Got\" key=r.key value=r.value offset=r.offset\n            commit_record(c, r)\n        end\n    end\nfinally\n    close(c) # unreachable here, Ctrl+C to stop\nend","category":"section"},{"location":"#Examples","page":"Home","title":"Examples","text":"Ready-to-run scripts are in examples/. See:\n\nexamples/simple_producer.jl\nexamples/simple_consumer.jl","category":"section"},{"location":"#API","page":"Home","title":"API","text":"See the Julia REPL help (e.g. ?KafkaProducer) for function and type documentation.","category":"section"},{"location":"#License","page":"Home","title":"License","text":"MIT License. See LICENSE in the repository.","category":"section"}]
